(7567271, 1213960, 104230, '<td valign="top">Congratulations on the ribbon, Lynn.  Wonderful shot. Lovely contrast and detail on the spires. Cars lined up at the crosswalk/light is another nice touch.</td>', 'Congratulations on the ribbon, Lynn.  Wonderful shot. Lovely contrast and detail on the spires. Cars lined up at the crosswalk/light is another nice touch.', '2018-04-29 15:05:40.000000', NULL, 0),
(7567327, 1213873, 25024, '<td valign="top">Hello from the critique club<br/> <br/>An interesting image that contributes well to the challenge<br/> <br/>A very symbolic and poignant image Susan, well seen and composed and ideal for the challenge. There is a very striking tension between the calm soothing tranquility suggested by the coloured window against the harsh aggressive roughness of the broken timbers and the crossed timbers of the beams. An excellent choice of viewpoint and composition has lifted this from a straight forward documentary record of an event in time to something much more meaningful, well done Susan.</td>', 'Hello from the critique club An interesting image that contributes well to the challenge A very symbolic and poignant image Susan, well seen and composed and ideal for the challenge. There is a very striking tension between the calm soothing tranquility suggested by the coloured window against the harsh aggressive roughness of the broken timbers and the crossed timbers of the beams. An excellent choice of viewpoint and composition has lifted this from a straight forward documentary record of an event in time to something much more meaningful, well done Susan.', '2018-04-30 07:38:32.000000', NULL, 0),
(7567351, 1213846, 185714, '<td valign="top">Beautiful! Congrats!</td>', 'Beautiful! Congrats!', '2018-04-30 11:22:52.000000', NULL, 0),
